<?php
set_time_limit(30); date_default_timezone_set('Asia/Dhaka'); require_once __DIR__.'/../../services/OltService.php';
$pdo=oltDb(); $view=$_GET['view']??'map'; $allowed=['map','traffic','usage','devices','alerts']; if(!in_array($view,$allowed,true))$view='map';
$olts=$pdo?oltGetActiveDevices():[]; $oltStats=[]; $topology=[]; $alerts=[];
if($pdo){
$q=$pdo->query("SELECT o.id,o.device_name,o.ip_address,o.snmp_port,COALESCE(u.onu_count,0) onu_count,COALESCE(u.rx_count,0) rx_count,COALESCE(u.tx_count,0) tx_count,COALESCE(u.download_bytes,0) download_bytes,COALESCE(u.upload_bytes,0) upload_bytes,u.last_updated FROM tbl_olt_devices o LEFT JOIN (SELECT olt_ip,COUNT(*) onu_count,SUM(rx_power IS NOT NULL AND rx_power <> '') rx_count,SUM(tx_power IS NOT NULL AND tx_power <> '') tx_count,SUM(download_bytes) download_bytes,SUM(upload_bytes) upload_bytes,MAX(last_updated) last_updated FROM onu_status GROUP BY olt_ip) u ON CONVERT(u.olt_ip USING utf8mb4) COLLATE utf8mb4_general_ci=CONVERT(o.ip_address USING utf8mb4) COLLATE utf8mb4_general_ci ORDER BY o.device_name"); $oltStats=$q->fetchAll(PDO::FETCH_ASSOC);
$t=$pdo->query("SELECT olt_ip,interface_name,COUNT(*) onu_count,SUM(download_bytes) download_bytes,SUM(upload_bytes) upload_bytes,AVG(rx_power) rx_power,AVG(tx_power) tx_power,MAX(last_updated) last_updated FROM onu_status GROUP BY olt_ip,interface_name ORDER BY olt_ip,interface_name"); $topology=$t->fetchAll(PDO::FETCH_ASSOC);
foreach($oltStats as $s){if(!(int)$s['onu_count'])$alerts[]=['danger','OLT has no collected ONU data',$s['device_name']];if($s['last_updated']&&strtotime($s['last_updated'])<time()-900)$alerts[]=['warning','ONU data is older than 15 minutes',$s['device_name']];}
try{$low=$pdo->query("SELECT interface_name,olt_ip,rx_power FROM onu_status WHERE rx_power IS NOT NULL AND rx_power < -30 ORDER BY rx_power LIMIT 20")->fetchAll(PDO::FETCH_ASSOC);foreach($low as $r)$alerts[]=['danger','Low RX power: '.$r['rx_power'].' dBm',$r['olt_ip'].' / '.$r['interface_name']];}catch(Throwable $e){}}
$totalOnu=array_sum(array_column($oltStats,'onu_count')); $totalRx=array_sum(array_column($oltStats,'rx_count')); $totalTx=array_sum(array_column($oltStats,'tx_count')); $totalDown=0; foreach($oltStats as $s)if(!(int)$s['onu_count'])$totalDown++;
function gb($v){return round((float)$v/1073741824,2);} $topologyJson=json_encode($topology,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT); $rootName=json_encode($oltStats[0]['device_name']??'OLT',JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT);
?>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><style>
.nm-wrap{padding:18px}.nm-nav{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}.nm-nav a{padding:9px 14px;border-radius:9px;text-decoration:none;background:#f1f5f9;color:#334155;font-weight:600}.nm-nav a.active{background:#2563eb;color:#fff}.nm-kpis{display:grid;grid-template-columns:repeat(5,minmax(120px,1fr));gap:12px;margin-bottom:16px}.nm-card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:14px;box-shadow:0 2px 8px rgba(15,23,42,.05)}.nm-kpi{font-size:24px;font-weight:700}.nm-muted{color:#64748b;font-size:12px}.nm-grid{display:grid;grid-template-columns:2fr 1fr;gap:16px}.nm-table{width:100%;border-collapse:collapse}.nm-table th,.nm-table td{padding:10px;border-bottom:1px solid #e5e7eb;text-align:left}.nm-table th{font-size:12px;color:#64748b}.nm-status{display:inline-block;padding:4px 8px;border-radius:999px;color:#fff;font-size:11px}.nm-alert{padding:10px;border-radius:8px;margin-bottom:8px;background:#fff7ed}.nm-map{height:560px;border-radius:12px;overflow:hidden}.nm-bar{height:8px;background:#e2e8f0;border-radius:10px;overflow:hidden}.nm-bar span{display:block;height:100%;background:#2563eb}.nm-big{font-size:34px;font-weight:800}.nm-legend{position:absolute;z-index:900;background:#fff;padding:8px 10px;border-radius:8px;box-shadow:0 2px 8px #0002;font-size:12px;margin:10px}.nm-node{font-weight:700}.nm-info{padding:8px}.nm-warning{margin-top:10px;padding:8px 10px;border-radius:8px;background:#fff7ed;color:#9a3412;font-size:12px}@media(max-width:900px){.nm-kpis{grid-template-columns:repeat(2,1fr)}.nm-grid{grid-template-columns:1fr}}
