<?php if($view==='map'): ?><div class="nm-grid"><div class="nm-card"><div id="nmMap" class="nm-map"></div><div class="nm-warning">Logical topology view: interface/ONU positions are derived from monitoring relationships. GPS coordinates are not stored yet, so this map does not claim physical locations.</div></div><div class="nm-card"><h6>Network Nodes</h6><?php foreach($oltStats as $s): ?><div class="d-flex justify-content-between align-items-center py-2 border-bottom"><div><strong><?=htmlspecialchars($s['device_name'])?></strong><div class="nm-muted"><?=htmlspecialchars($s['ip_address'])?>:<?=intval($s['snmp_port'])?></div></div><span class="nm-status <?=$s['onu_count']?'bg-success':'bg-danger'?>"><?=intval($s['onu_count'])?> ONUs</span></div><?php endforeach;?><hr><div class="nm-muted">Interface clusters: <?=count($topology)?></div></div></div>
<?php elseif($view==='traffic'): ?><div class="nm-grid"><div class="nm-card"><h6>OLT Traffic</h6><table class="nm-table"><thead><tr><th>Device</th><th>Download</th><th>Upload</th></tr></thead><tbody><?php foreach($oltStats as $s): ?><tr><td><?=htmlspecialchars($s['device_name'])?></td><td><?=gb($s['download_bytes'])?> GB</td><td><?=gb($s['upload_bytes'])?> GB</td></tr><?php endforeach;?></tbody></table></div><div class="nm-card"><div class="nm-muted">Total Download</div><div class="nm-big"><?=gb(array_sum(array_column($oltStats,'download_bytes')))?></div><hr><div class="nm-muted">Total Upload</div><div class="nm-big"><?=gb(array_sum(array_column($oltStats,'upload_bytes')))?></div></div></div>
<?php elseif($view==='usage'): ?><div class="nm-card"><h6>High Usage Monitor</h6><?php $rows=[];if($pdo){try{$rows=$pdo->query("SELECT olt_ip,interface_name,serial,COALESCE(download_bytes,0)+COALESCE(upload_bytes,0) total_bytes FROM onu_status ORDER BY total_bytes DESC LIMIT 20")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){}}$max=$rows?max(array_column($rows,'total_bytes')):1; ?><table class="nm-table"><thead><tr><th>OLT</th><th>Interface</th><th>Serial</th><th>Usage</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=htmlspecialchars($r['olt_ip'])?></td><td><?=htmlspecialchars($r['interface_name'])?></td><td><?=htmlspecialchars($r['serial'])?></td><td><strong><?=gb($r['total_bytes'])?> GB</strong><div class="nm-bar"><span style="width:<?=min(100,((float)$r['total_bytes']/$max)*100)?>%"></span></div></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($view==='devices'): ?><div class="nm-card"><h6>Device Watcher</h6><table class="nm-table"><thead><tr><th>Device</th><th>IP</th><th>ONU Count</th><th>Last Data</th><th>Status</th></tr></thead><tbody><?php foreach($oltStats as $s):$fresh=$s['last_updated']&&strtotime($s['last_updated'])>=time()-900&&(int)$s['onu_count']>0; ?><tr><td><?=htmlspecialchars($s['device_name'])?></td><td><?=htmlspecialchars($s['ip_address'])?></td><td><?=intval($s['onu_count'])?></td><td><?=htmlspecialchars($s['last_updated']??'-')?></td><td><span class="nm-status <?=$fresh?'bg-success':'bg-danger'?>"><?=$fresh?'ONLINE':'WATCH'?></span></td></tr><?php endforeach;?></tbody></table></div>
<?php else: ?><div class="nm-card"><h6>Logs & Alerts</h6><?php if(!$alerts): ?><div class="alert alert-success">No active monitoring alerts detected.</div><?php else:foreach($alerts as $a): ?><div class="nm-alert"><strong><?=htmlspecialchars($a[1])?></strong><div class="nm-muted"><?=htmlspecialchars($a[2])?></div></div><?php endforeach;endif;?></div><?php endif; ?></div>
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>document.addEventListener('DOMContentLoaded',function(){var e=document.getElementById('nmMap');if(!e||typeof L==='undefined')return;var rows=<?=$topologyJson?:'[]'?>,m=L.map('nmMap').setView([23.8103,90.4125],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(m);var olt=<?=$rootName?>;var center=[23.8103,90.4125],root=L.circleMarker(center,{radius:14,color:'#2563eb',fillColor:'#2563eb',fillOpacity:.9}).addTo(m).bindPopup('<div class="nm-info"><div class="nm-node">'+olt+'</div><div>OLT root</div></div>');var n=Math.max(rows.length,1),bounds=[center];rows.forEach(function(r,i){var a=(Math.PI*2*i/n)-Math.PI/2,d=0.025+Math.min(0.02,i/Math.max(n,1)*0.015),p=[center[0]+Math.sin(a)*d,center[1]+Math.cos(a)*d];var c=L.circleMarker(p,{radius:Math.min(14,7+Math.log10(Math.max(1,r.onu_count))*4),color:r.onu_count?'#16a34a':'#dc2626',fillColor:r.onu_count?'#22c55e':'#ef4444',fillOpacity:.85}).addTo(m).bindPopup('<div class="nm-info"><div class="nm-node">'+r.interface_name+'</div><div>'+r.onu_count+' ONUs</div><div>RX '+(r.rx_power===null?'-':Number(r.rx_power).toFixed(2))+' dBm</div><div>TX '+(r.tx_power===null?'-':Number(r.tx_power).toFixed(2))+' dBm</div></div>');L.polyline([center,p],{color:r.onu_count?'#16a34a':'#dc2626',weight:3,opacity:.7}).addTo(m);bounds.push(p)});if(bounds.length>1)m.fitBounds(bounds,{padding:[25,25]});});</script>
